package com.alpharip.staffmod.RuleReferenceOverlay;
import net.minecraft.client.gui.*;import java.io.IOException;import java.util.*;
/** Initial in-game reference panel. Requires a real StaffMods access adapter from its caller. */
public final class RuleReferenceOverlayGui extends GuiScreen {
 private static final int BACK=1,CATEGORY=100;private final GuiScreen parent;private final RuleReferenceController controller;private RuleCategory selected=RuleCategory.CHAT;private RuleReferenceResult result=new RuleReferenceResult(null);private int left,top,right,bottom;private String message="LOCAL RULE DATA";
 public RuleReferenceOverlayGui(GuiScreen parent,RuleReferenceController controller){if(controller==null)throw new IllegalArgumentException("controller");this.parent=parent;this.controller=controller;}
 @Override public void initGui(){if(!controller.canView()){mc.displayGuiScreen(parent);return;}int w=Math.min(520,width-20),h=Math.min(330,height-20);left=(width-w)/2;right=left+w;top=(height-h)/2;bottom=top+h;buttonList.clear();int x=left+12;for(RuleCategory c:RuleCategory.values()){buttonList.add(new GuiButton(CATEGORY+c.ordinal(),x,top+48,82,20,c.name()));x+=86;}buttonList.add(new GuiButton(BACK,left+12,bottom-28,70,20,"BACK"));refresh();}
 private void refresh(){result=controller.find(new RuleContext(selected,""));message="CATEGORY: "+selected.name()+" · "+result.getMatches().size()+" RULES";}
 @Override protected void actionPerformed(GuiButton b)throws IOException{if(b.id==BACK){mc.displayGuiScreen(parent);return;}if(b.id>=CATEGORY&&b.id<CATEGORY+RuleCategory.values().length){selected=RuleCategory.values()[b.id-CATEGORY];refresh();}}
 @Override public void drawScreen(int mx,int my,float partial){drawDefaultBackground();drawRect(left,top,right,bottom,0xF00D1017);drawRect(left,top,right,top+2,0xFFFFD866);drawCenteredString(fontRendererObj,"RULE REFERENCE",width/2,top+14,0xFFF3F4F6);drawCenteredString(fontRendererObj,"STAFF OPERATIONS · LOCAL PROTOTYPE",width/2,top+30,0xFFFFD866);int y=top+82;if(result.isEmpty())drawString(fontRendererObj,"No local rules available for this category.",left+16,y,0xFFB8BDC8);else for(RuleMatch m:result.getMatches()){RuleEntry r=m.getRule();drawRect(left+12,y-4,right-12,y+34,0xAA191D25);drawString(fontRendererObj,fontRendererObj.trimStringToWidth(r.getTitle(),right-left-32),left+20,y,0xFFF3F4F6);drawString(fontRendererObj,fontRendererObj.trimStringToWidth(r.getDescription(),right-left-32),left+20,y+13,0xFFB8BDC8);drawString(fontRendererObj,r.getSeverity().name(),left+20,y+25,0xFFFFD866);y+=43;if(y>bottom-52)break;}drawString(fontRendererObj,message,left+100,bottom-24,0xFFB8BDC8);super.drawScreen(mx,my,partial);}
 @Override protected void keyTyped(char c,int key)throws IOException{if(key==1)mc.displayGuiScreen(parent);else super.keyTyped(c,key);}
 @Override public boolean doesGuiPauseGame(){return false;}
}